24	// baseParam provides common parameter functionality.
25	type baseParam struct {
26		name         string
27		paramType    ParamType
28		required     bool // when true, emits "!" marker — user must explicitly provide this field in input
29		optional     bool // when true, emits "?" marker — field may be absent from input
30		defaultValue any
31		description  string
32		short        string // short flag alias (e.g. "i" → // +short=i)
33		ignore       bool   // when true, emits // +ignore directive
34	}
35	
36	func (p *baseParam) expr()      {}
37	func (p *baseParam) value()     {}
38	func (p *baseParam) condition() {}
39	
40	func (p *baseParam) Name() string           { return p.name }
41	func (p *baseParam) IsRequired() bool       { return p.required }
42	func (p *baseParam) IsOptional() bool       { return p.optional }
43	func (p *baseParam) HasDefault() bool       { return p.defaultValue != nil }
44	func (p *baseParam) GetDefault() any        { return p.defaultValue }
45	func (p *baseParam) GetDescription() string { return p.description }
46	func (p *baseParam) GetShort() string       { return p.short }
47	func (p *baseParam) IsIgnore() bool         { return p.ignore }
48	
49	// IsSet returns a condition that checks if the parameter has a value.
50	// This is used with SetIf for conditional field assignment.
51	func (p *baseParam) IsSet() Condition {
52		return &IsSetCondition{paramName: p.name}
53	}
54	
55	// NotSet returns a condition that checks if the parameter is not set.
56	// This generates `if parameter["name"] == _|_` in CUE.
57	func (p *baseParam) NotSet() Condition {
58		return Not(&IsSetCondition{paramName: p.name})
59	}
60	
61	// Eq creates a condition that compares this parameter to a literal value.
62	// Example: replicas.Eq(3) generates: parameter.replicas == 3
63	func (p *baseParam) Eq(val any) Condition {
64		return &ParamCompareCondition{paramName: p.name, op: "==", value: val}
65	}
66	
67	// Ne creates a condition that checks if this parameter is not equal to a value.
68	// Example: status.Ne("error") generates: parameter.status != "error"
69	func (p *baseParam) Ne(val any) Condition {
70		return &ParamCompareCondition{paramName: p.name, op: "!=", value: val}
71	}
72	
73	// Gt creates a condition that checks if this parameter is greater than a value.
74	// Example: replicas.Gt(1) generates: parameter.replicas > 1
75	func (p *baseParam) Gt(val any) Condition {
76		return &ParamCompareCondition{paramName: p.name, op: ">", value: val}
77	}
78	
79	// Gte creates a condition that checks if this parameter is greater than or equal to a value.
80	// Example: replicas.Gte(1) generates: parameter.replicas >= 1
81	func (p *baseParam) Gte(val any) Condition {
82		return &ParamCompareCondition{paramName: p.name, op: ">=", value: val}
83	}
84	
85	// Lt creates a condition that checks if this parameter is less than a value.
86	// Example: replicas.Lt(10) generates: parameter.replicas < 10
87	func (p *baseParam) Lt(val any) Condition {
88		return &ParamCompareCondition{paramName: p.name, op: "<", value: val}
89	}
90	
91	// Lte creates a condition that checks if this parameter is less than or equal to a value.
92	// Example: replicas.Lte(10) generates: parameter.replicas <= 10
93	func (p *baseParam) Lte(val any) Condition {
94		return &ParamCompareCondition{paramName: p.name, op: "<=", value: val}
95	}
96	
97	// ParamCompareCondition represents a comparison between a parameter and a value.
98	type ParamCompareCondition struct {
99		baseCondition
100		paramName string
101		op        string
102		value     any
103	}
104	
105	// ParamName returns the parameter name being compared.
106	func (c *ParamCompareCondition) ParamName() string { return c.paramName }
107	
108	// Op returns the comparison operator.
109	func (c *ParamCompareCondition) Op() string { return c.op }
110	
111	// CompareValue returns the comparison value.
112	func (c *ParamCompareCondition) CompareValue() any { return c.value }
113	
114	// StringParam represents a string parameter.
115	type StringParam struct {
116		baseParam
117		enumValues []string // allowed enum values
118		openEnum   bool     // when true, appends | string to enum disjunction (open enum)
119		pattern    string   // regex pattern constraint
120		notEmpty   bool     // when true, emits !="" constraint
121		minLen     *int     // minimum length constraint
122		maxLen     *int     // maximum length constraint
123	}
124	
125	// String creates a new string parameter with the given name.
126	func String(name string) *StringParam {
127		return &StringParam{
128			baseParam: baseParam{
129				name:      name,
130				paramType: ParamTypeString,
131			},
132		}
133	}
134	
135	// Required marks the parameter as required in input, emitting the "!" CUE marker.
136	// The user must explicitly provide this field — even if a default value exists.
137	func (p *StringParam) Required() *StringParam {
138		p.required = true
139		p.optional = false
140		return p
141	}
142	
143	// Optional marks the parameter as optional, emitting the "?" CUE marker.
144	// The field may be absent from input entirely.
145	func (p *StringParam) Optional() *StringParam {
146		p.optional = true
147		p.required = false
148		return p
149	}
150	
151	// Short sets a short flag alias for the parameter.
152	// This generates a // +short=X directive in the CUE output.
153	func (p *StringParam) Short(s string) *StringParam {
154		p.short = s
155		return p
156	}
157	
158	// Ignore marks the parameter as ignored by the UI.
159	// This generates a // +ignore directive in the CUE output.
160	func (p *StringParam) Ignore() *StringParam {
161		p.ignore = true
162		return p
163	}
164	
165	// Default sets a default value for the parameter.
166	func (p *StringParam) Default(value string) *StringParam {
167		p.defaultValue = value
168		return p
169	}
170	
171	// Description sets the parameter description.
172	func (p *StringParam) Description(desc string) *StringParam {
173		p.description = desc
174		return p
175	}
176	
177	// Values restricts the parameter to specific allowed values.
178	func (p *StringParam) Values(values ...string) *StringParam {
179		p.enumValues = values
180		return p
181	}
182	
183	// GetEnumValues returns the allowed enum values.
184	func (p *StringParam) GetEnumValues() []string {
185		return p.enumValues
186	}
187	
188	// OpenEnum marks the enum as open, allowing any string in addition to the
189	// enumerated values. This generates CUE like: "value1" | "value2" | string
190	func (p *StringParam) OpenEnum() *StringParam {
191		p.openEnum = true
192		return p
193	}
194	
195	// IsOpenEnum returns whether the enum allows arbitrary strings beyond the listed values.
196	func (p *StringParam) IsOpenEnum() bool {
197		return p.openEnum
198	}
199	
200	// Pattern sets a regex pattern constraint for the parameter.
201	// This generates CUE like: string & =~"pattern"
202	func (p *StringParam) Pattern(regex string) *StringParam {
203		p.pattern = regex
204		return p
205	}
206	
207	// GetPattern returns the regex pattern constraint.
208	func (p *StringParam) GetPattern() string {
209		return p.pattern
210	}
211	
