1938	// canDecomposeByCondition checks if a struct node's children can be split into
1939	// separate conditional blocks. This is possible when every child subtree has
1940	// the same uniform set of leaf conditions (e.g., every leaf is guarded by either
1941	// condition A or condition B). Returns a map of conditionString -> childNames,
1942	// or nil if decomposition is not possible.
1943	func (g *CUEGenerator) canDecomposeByCondition(node *fieldNode) map[string][]string {
1944		if node.value != nil || len(node.spreads) > 0 || node.forEach != nil || node.patchKey != nil {
1945			return nil
1946		}
1947		if len(node.children) == 0 {
1948			return nil
1949		}
1950	
1951		// Collect the set of leaf conditions from each child subtree
1952		childCondSets := make(map[string]map[string]bool)
1953		for _, childName := range node.childOrder {
1954			child := node.children[childName]
1955			condSet := make(map[string]bool)
1956			g.collectLeafConditions(child, condSet)
1957			if len(condSet) == 0 {
1958				return nil
1959			}
1960			// If any leaf is unconditional (empty string), can't decompose
1961			if condSet[""] {
1962				return nil
1963			}
1964			childCondSets[childName] = condSet
1965		}
1966	
1967		// All children must have the same condition set
1968		var referenceSet map[string]bool
1969		for _, condSet := range childCondSets {
1970			if referenceSet == nil {
1971				referenceSet = condSet
1972			} else {
1973				if len(condSet) != len(referenceSet) {
1974					return nil
1975				}
1976				for k := range referenceSet {
1977					if !condSet[k] {
1978						return nil
1979					}
1980				}
1981			}
1982		}
1983	
1984		// Need at least 2 different conditions to warrant decomposition
1985		if len(referenceSet) < 2 {
1986			return nil
1987		}
1988	
1989		result := make(map[string][]string)
1990		for condStr := range referenceSet {
1991			result[condStr] = append(result[condStr], node.childOrder...)
1992		}
1993		return result
1994	}
