1996	// collectLeafConditions traverses a subtree and collects the CUE string
1997	// representations of all leaf conditions. An unconditional leaf adds "".
1998	func (g *CUEGenerator) collectLeafConditions(node *fieldNode, condSet map[string]bool) {
1999		if node.cond != nil && node.value != nil {
2000			condSet[g.conditionToCUE(node.cond)] = true
2001			// Also collect conditions from condValues (additional conditional
2002			// values at the same path).
2003			for _, cv := range node.condValues {
2004				condSet[g.conditionToCUE(cv.cond)] = true
2005			}
2006			return
2007		}
2008		if node.cond != nil && len(node.children) > 0 {
2009			// Intermediate node with a condition (already lifted)
2010			condSet[g.conditionToCUE(node.cond)] = true
2011			return
2012		}
2013		if node.value != nil && node.cond == nil {
2014			condSet[""] = true
2015			return
2016		}
2017		for _, childName := range node.childOrder {
2018			child := node.children[childName]
2019			g.collectLeafConditions(child, condSet)
2020		}
2021	}
