2023	// filterNodeByCondition returns a copy of the subtree containing only leaves
2024	// that match the given condition string. Intermediate nodes have their
2025	// conditions cleared since the caller wraps the result in the condition block.
2026	func (g *CUEGenerator) filterNodeByCondition(node *fieldNode, condStr string) *fieldNode {
2027		if node.cond != nil {
2028			if g.conditionToCUE(node.cond) == condStr {
2029				nodeCopy := *node
2030				nodeCopy.cond = nil
2031				nodeCopy.condValues = nil // Strip condValues; other conditions handled by their own block
2032				return &nodeCopy
2033			}
2034			// Check if the target condition is in condValues instead of the primary
2035			for _, cv := range node.condValues {
2036				if g.conditionToCUE(cv.cond) == condStr {
2037					nodeCopy := *node
2038					nodeCopy.value = cv.value
2039					nodeCopy.cond = nil
2040					nodeCopy.condValues = nil
2041					return &nodeCopy
2042				}
2043			}
2044			return nil
2045		}
2046	
2047		filtered := &fieldNode{
2048			children:   make(map[string]*fieldNode),
2049			childOrder: make([]string, 0),
2050			value:      node.value,
2051		}
2052		for _, childName := range node.childOrder {
2053			child := node.children[childName]
2054			filteredChild := g.filterNodeByCondition(child, condStr)
2055			if filteredChild != nil {
2056				filtered.children[childName] = filteredChild
2057				filtered.childOrder = append(filtered.childOrder, childName)
2058			}
2059		}
2060		if len(filtered.children) == 0 && filtered.value == nil {
2061			return nil
2062		}
2063		return filtered
2064	}
