2066	// tryRenderBuilder checks if a Value implements CUERenderer or CUEConditionRenderer
2067	// and renders it. Returns empty string if the value is not a builder.
2068	func (g *CUEGenerator) tryRenderBuilder(v Value) string {
2069		if ccr, ok := v.(CUEConditionRenderer); ok {
2070			return ccr.RenderCUEWithCondition(g.valueToCUE, g.conditionToCUE)
