510	func parseBracketAccess(part string) (name string, key string, index int) {
511		for i, c := range part {
512			if c == '[' {
513				if part[len(part)-1] != ']' {
514					return part, "", -1
515				}
516				name = part[:i]
517				bracketContent := part[i+1 : len(part)-1]
518				// Check if the content is numeric (array index)
519				isNumeric := len(bracketContent) > 0
520				for _, d := range bracketContent {
521					if d < '0' || d > '9' {
522						isNumeric = false
